Description['ual0402']    = "The Overlord is mounted with a light Phason Laser, a SAM launcher for anti air defence, a shoulder cannon and a photon blaster. It can also walk under water. While being a weaker experimental, the Overlord is good for multiple purposes."
Description['ual0402-cd'] = "Creates a Quantum Stasis Field around the Overlord. Immoblizes enemy units within its radius. High Energy Consumption."
Description['uel0402']    = "A showpiece of UEF technology, the Rampage brings a lot of firepower to the battlefield for its size -- warnings have been issued about its volatility."
Description['ssl0403']    = "<LOC Unit_Description_BrewLAN_T4L001>Experimental amphibious repair, capture, and reclamation unit. Gains the blueprints of units and wreckages by reclaiming them."
Description['veb2302']    = "A Tech 4 level AA missile weapon that causes huge damage. Ignores Tech 1 air units."
Description['wel0401']    = "The Littleman is a combat refit of the original Fatboy; swapping the factory for an artillery. Designed to provide ranged support for battlegroups."
Description['wsl0404']    = "Experimental Mobile Field Artillery with a local close defense weapon and AA."
Description['mkt0409']    = "Experimental assault transport and carrier. Carries land units up to experimental size. Armed with two railguns, anti-air missiles, flak and two phalanx gatlings."
